-- Meero pivot — generative 3D scenes instead of mobile apps.
--
-- Every plan now builds the SAME thing: a real, live-interactive Three.js
-- scene, generated by the codegen agent and bundled (esbuild) on a plain
-- Linux worker — no per-platform target to choose between anymore, so a
-- single 'scene' build_platform value replaces ios/android/expo going
-- forward (old rows keep their historical value; enums can't drop values).
--
-- Ultra additionally unlocks a real headless Blender (Cycles) cinematic
-- render as a separate, explicitly user-triggered action per build — never
-- part of the base pipeline, so free/pro never pay for render-farm time.
--
-- NOTE: `alter type ... add value` cannot run in the same transaction as a
-- statement that reads/writes a row using the new value.
alter type public.build_platform add value if not exists 'scene';

-- build_artifacts.kind: replace the mobile-specific vocabulary with the new
-- pipeline's artifact kinds. 'source_archive' and 'log' are unchanged and
-- reused as-is; 'app_bundle'/'apk'/'aab' are dropped from the allowed set
-- for NEW rows. Historical rows from the mobile-app-builder era already
-- carry those old kind values, so the new CHECK is added `not valid` —
-- Postgres otherwise validates EVERY existing row against a freshly-added
-- constraint (not just new ones), which fails immediately on this table.
-- `not valid` still enforces the check on every future insert/update; it
-- just skips the one-time historical backfill scan.
alter table public.build_artifacts drop constraint build_artifacts_kind_check;
alter table public.build_artifacts add constraint build_artifacts_kind_check
  check (kind in (
    'source_archive',  -- the generated Three.js/TypeScript project, zipped
    'web_bundle',       -- esbuild output (bundle.js + index.html) actually served as the preview
    'render_video',     -- ultra: real Blender/Cycles output, encoded to mp4
    'render_frames',    -- ultra: real Blender/Cycles raw PNG frame sequence, zipped
    'log'
  )) not valid;

-- projects.platforms and projects.eas_project_id were mobile-framework
-- concepts (which native targets to compile, Expo Go scan links) with no
-- equivalent here — every project now builds one implicit thing. Drop both;
-- the CHECK constraint on platforms must go first since it references the
-- column being dropped.
alter table public.projects drop constraint if exists projects_platforms_check;
alter table public.projects drop column if exists platforms;
alter table public.projects drop column if exists eas_project_id;

-- PUBLIC previews bucket already exists (00011_expo_platform.sql) and is
-- reused verbatim: the scene worker uploads bundle.js/index.html there
-- instead of an Expo web export, served through the same /preview proxy.
